import{_ as e}from"./plugin-vue_export-helper-c27b6911.js";import{o as d,c as l,e as a}from"./app-89d18e81.js";const i={},o=a('<h1 id="adb-android-debug-bridge-命令大全" tabindex="-1"><a class="header-anchor" href="#adb-android-debug-bridge-命令大全" aria-hidden="true">#</a> ADB (Android Debug Bridge) 命令大全</h1><p>Android 调试桥 (adb) 是一种功能多样的命令行工具，可让您与设备进行通信。</p><h2 id="_1-基础连接命令" tabindex="-1"><a class="header-anchor" href="#_1-基础连接命令" aria-hidden="true">#</a> 1. 基础连接命令</h2><ul><li><code>adb devices</code>: 查看当前连接的设备列表。</li><li><code>adb get-state</code>: 获取设备状态 (device, recovery, unknown, offline)。</li><li><code>adb kill-server</code>: 终止 adb 服务。</li><li><code>adb start-server</code>: 启动 adb 服务。</li><li><code>adb -s &lt;serial_number&gt; &lt;command&gt;</code>: 对指定序列号的设备执行命令。</li></ul><h2 id="_2-无线连接-adb-over-wifi" tabindex="-1"><a class="header-anchor" href="#_2-无线连接-adb-over-wifi" aria-hidden="true">#</a> 2. 无线连接 (ADB over WiFi)</h2><ol><li>将设备通过 USB 连接到电脑。</li><li><code>adb tcpip 5555</code>: 设置设备监听端口。</li><li>断开 USB 连接。</li><li><code>adb connect &lt;device_ip_address&gt;:5555</code>: 连接到设备。</li><li><code>adb disconnect</code>: 断开连接。</li></ol><h2 id="_3-文件操作" tabindex="-1"><a class="header-anchor" href="#_3-文件操作" aria-hidden="true">#</a> 3. 文件操作</h2><ul><li><code>adb push &lt;local&gt; &lt;remote&gt;</code>: 将文件/目录从电脑推送到设备。</li><li><code>adb pull &lt;remote&gt; &lt;local&gt;</code>: 将文件/目录从设备拉取到电脑。</li><li><code>adb shell ls /sdcard/</code>: 查看设备文件目录。</li></ul><h2 id="_4-应用管理" tabindex="-1"><a class="header-anchor" href="#_4-应用管理" aria-hidden="true">#</a> 4. 应用管理</h2><ul><li><code>adb install &lt;path_to_apk&gt;</code>: 安装 APK。</li><li><code>adb install -r &lt;path_to_apk&gt;</code>: 覆盖安装。</li><li><code>adb uninstall &lt;package_name&gt;</code>: 卸载应用。</li><li><code>adb uninstall -k &lt;package_name&gt;</code>: 卸载应用但保留数据和缓存。</li><li><code>adb shell pm list packages</code>: 列出所有已安装的包名。 <ul><li><code>-s</code>: 只列出系统应用。</li><li><code>-3</code>: 只列出第三方应用。</li><li><code>-f</code>: 显示关联的 APK 文件路径。</li></ul></li><li><code>adb shell pm path &lt;package_name&gt;</code>: 查看应用的安装路径。</li><li><code>adb shell pm clear &lt;package_name&gt;</code>: 清除应用数据和缓存。</li></ul><h2 id="_5-交互与调试" tabindex="-1"><a class="header-anchor" href="#_5-交互与调试" aria-hidden="true">#</a> 5. 交互与调试</h2><ul><li><code>adb shell</code>: 进入设备的 shell 模式。</li><li><code>adb logcat</code>: 查看实时日志。 <ul><li><code>adb logcat *:E</code>: 只查看错误级别日志。</li><li><code>adb logcat -c</code>: 清除旧日志。</li></ul></li><li><code>adb shell dumpsys activity top</code>: 查看当前栈顶 Activity。</li><li><code>adb shell am start -n &lt;package&gt;/&lt;activity&gt;</code>: 启动指定 Activity。</li><li><code>adb shell am force-stop &lt;package&gt;</code>: 强制停止应用。</li><li><code>adb shell input text &lt;text&gt;</code>: 模拟输入文本。</li><li><code>adb shell input tap &lt;x&gt; &lt;y&gt;</code>: 模拟点击。</li><li><code>adb shell input keyevent &lt;keycode&gt;</code>: 模拟按键（如 26 为电源键，66 为回车）。</li></ul><h2 id="_6-系统与信息" tabindex="-1"><a class="header-anchor" href="#_6-系统与信息" aria-hidden="true">#</a> 6. 系统与信息</h2><ul><li><code>adb shell getprop ro.product.model</code>: 获取设备型号。</li><li><code>adb shell getprop ro.build.version.release</code>: 获取 Android 版本。</li><li><code>adb shell wm size</code>: 查看屏幕分辨率。</li><li><code>adb shell wm density</code>: 查看屏幕密度。</li><li><code>adb shell screencap /sdcard/screen.png</code>: 屏幕截图。</li><li><code>adb shell screenrecord /sdcard/demo.mp4</code>: 录制屏幕。</li></ul><h2 id="_7-刷机相关" tabindex="-1"><a class="header-anchor" href="#_7-刷机相关" aria-hidden="true">#</a> 7. 刷机相关</h2><ul><li><code>adb reboot</code>: 重启设备。</li><li><code>adb reboot recovery</code>: 重启到 Recovery 模式。</li><li><code>adb reboot bootloader</code>: 重启到 Fastboot 模式。</li><li><code>adb sideload &lt;ota.zip&gt;</code>: 线刷固件包。</li></ul>',16),c=[o];function t(r,s){return d(),l("div",null,c)}const b=e(i,[["render",t],["__file","adb.html.vue"]]);export{b as default};
